output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles, i.e. narrow aisles with shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "Agents must not move into a single-file shelf aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        }
      },
      "events": {
        "cartedEntryToSingleFileAisle": {
          "pre": {
            "and": [
              "hasCart",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W",
                  "MOVE"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartedEntryToSingleFileAisle"
    }
  },
  {
    "id": "park_cart_only_wide_open",
    "text": "If an agent sets down a cart, it must be parked in a wide open cross-aisle rather than beside shelves or in a bottleneck.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "openAisle": {
          "and": [
            "wideAisle",
            {
              "not": "adjShelf"
            }
          ]
        },
        "safeCartParking": "openAisle"
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "safeCartParking"
          }
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_parking",
    "text": "Whenever an agent parks the cart in order to proceed on foot, they are obliged to retrieve a cart before leaving.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "openAisle": {
          "and": [
            "wideAisle",
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "openAisle"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "return_to_cart_after_on_foot_shelf_pick",
    "text": "After interacting with a shelf while on foot in a single-file aisle, the agent must return and retrieve the cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        }
      },
      "events": {
        "onFootShelfInteraction": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle"
            ]
          },
          "post": null
        },
        "retrieveCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "onFootShelfInteraction",
      "discharge": "retrieveCart"
    }
  },
  {
    "id": "no_roaming_open_aisles_without_cart",
    "text": "Except for the initial move from the entrance toward the cart, agents should not roam from one open aisle cell to another while not holding a cart.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "openAisle": {
          "and": [
            "wideAisle",
            {
              "not": "adjShelf"
            }
          ]
        },
        "initialEntranceCell": "at(0,7)"
      },
      "events": {
        "openAisleMoveOnFootAfterEntry": {
          "pre": {
            "and": [
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W",
                  "MOVE"
                ]
              },
              {
                "not": "hasCart"
              },
              "openAisle",
              {
                "not": "initialEntranceCell"
              }
            ]
          },
          "post": "openAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "openAisleMoveOnFootAfterEntry"
    }
  },
  {
    "id": "must_take_cart_at_start",
    "text": "Upon entering the supermarket, an agent is obliged to acquire a shopping cart.",
    "abstraction": {
      "state_properties": {
        "cartPossessed": "hasCart"
      },
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              }
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "cartPossessed"
    }
  },
  {
    "id": "no_cart_shelf_interaction_single_file",
    "text": "Agents are forbidden to interact with shelves in a single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFile": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "betweenShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "singleFile",
            "betweenShelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  }
]
